const q = $input.item.json.query || {};
const body = $input.item.json.body || {};
const p = { ...body, ...q };

const orderId = p.id || 'PED-DESCONOCIDO';
const name = p.name || 'Cliente';
const surname = p.surname || 'Cliente';
const phone = String(p.phone || '').replace(/\D/g, '').slice(-10);
const state = (p.state || 'ANTIOQUIA').toUpperCase();
const city = (p.city || 'MEDELLIN').toUpperCase();
const dir = p.dir || 'Direccion no provista';
const total = Number(p.total) || 29900;
const quantity = Number(p.quantity) || 1;
const notes = p.notes || '';
const productId = 2289560;

const token = "eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9..LkZwEaP3vQA7KenxkXaT8VMms1jNZMoeHIUno7FGr1lFqcsCRsqDtjgptw4CDHoa6Kfhd8EkqVuRoSyKh8OohCGvoORbrDunpm_f-Rq642QNJC_PqoXFKaxuj1P2S0pJ5i4avqpbxokKeD13nL6pqzxJ9R1FfShEQaLGfDhDKGVeivmFxnxdp-fEsTMI7D6pDxxRcJykxF6HxgDNKqgbSZLYqNRpJc9aTUwNlCeK1sGoEI0Ht5AWGLyoo9w_1p1KYYIL1w8SSVeeAisXvaZ4vL_yix461aOgKMqz4SX1v0ZFKahldktsddYT-59ZUqwnxWE2vX19KZg4WZ7exXjWXA";

// 1. Iniciar sesión MCP
const initRes = await fetch("https://mcp.dropi.co/mcp", {
  method: "POST",
  headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json" },
  body: JSON.stringify({
    jsonrpc: "2.0", id: 1, method: "initialize",
    params: { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "n8n", version: "1.0" } }
  })
});
const sessionId = initRes.headers.get("mcp-session-id");

await fetch("https://mcp.dropi.co/mcp", {
  method: "POST",
  headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json", ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
  body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" })
});

// 2. Crear Orden
const unitPrice = Math.round(total / quantity);
const toolRes = await fetch("https://mcp.dropi.co/mcp", {
  method: "POST",
  headers: { "Authorization": "Bearer " + token, "Content-Type": "application/json", ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
  body: JSON.stringify({
    jsonrpc: "2.0", id: 2, method: "tools/call",
    params: {
      name: "create_order",
      arguments: {
        name, surname, dir, state, city, phone,
        rate_type: "CON RECAUDO",
        notes, shop_order_id: orderId,
        products: [{ id: productId, price: unitPrice, quantity }]
      }
    }
  })
});

const rawText = await toolRes.text();
let dropiResult = {};
for (const line of rawText.split("\n")) {
  if (line.startsWith("data: ")) {
    try {
      const parsed = JSON.parse(line.slice(6));
      dropiResult = parsed.result || parsed.error || {};
    } catch (_) {}
    break;
  }
}

return {
  orderId,
  customerName: name + " " + surname,
  phone,
  state,
  city,
  dir,
  total,
  quantity,
  totalFormateado: "$" + total.toLocaleString("es-CO"),
  dropiResult,
  rawText
};
